def contact_bundle():
    """Ship a single deferred script; keep the contact core importable in tests."""
    core=(ROOT/'assets/js/contact-core.js').read_text()
    ui=(ROOT/'assets/js/contact.js').read_text()
    assert ui.startswith('import {')
    script="// Generated by scripts/render.py from contact-core.js and contact.js.\n(() => {\n'use strict';\n"
    script+=re.sub(r'^export ', '', core, flags=re.MULTILINE)+'\n'+ui.split('\n',1)[1]+'\n})();\n'
    (ROOT/'assets/js/contact-bundle.js').write_text(script)

def e(s): return escape(str(s), quote=True)
def external(url, label, cls=''): return f'<a href="{e(url)}" target="_blank" rel="noopener noreferrer" class="{cls}">{label}</a>'
def repo_url(p): return GITHUB+p['repo']+('/tree/'+p['branch'] if p.get('branch') else '')
def brand(): return '<a class="brand" href="index.html" aria-label="MATRIZ — início"><img src="assets/brand/logo-matriz.png" alt="" width="47" height="47"><strong itemprop="name">MATRIZ</strong></a>'
def action(href,label,primary=False): return f'<a class="button {"primary" if primary else "secondary"}" href="{e(href)}">{label}<span aria-hidden="true">↗</span></a>'
def nav(active):
    links=[('index.html#solucoes','Soluções'),('index.html#projetos','Projetos'),('index.html#produtos','O que criamos'),('index.html#processo','Como funciona')]
    navlinks=''.join(f'<a href="{url}"'+(' aria-current="page"' if active==url else '')+f'>{label}</a>' for url,label in links)
    return f'''<a class="skip-link" href="#main-content">Pular para o conteúdo</a>
<header class="site-header"><div class="container header-inner">{brand()}
<button class="menu-toggle" type="button" aria-controls="main-nav" aria-expanded="false" aria-label="Abrir menu"><span>Menu</span><i aria-hidden="true"></i></button>
<nav class="main-nav" id="main-nav" aria-label="Navegação principal">{navlinks}<a class="mobile-contact" href="contact.html">Vamos conversar ↗</a></nav>
<a class="button header-cta" href="contact.html">Vamos conversar <span aria-hidden="true">↗</span></a></div><span class="scroll-progress" aria-hidden="true"></span></header>'''
def footer(): return f'''<footer class="site-footer"><div class="container"><div class="footer-top"><div class="footer-brand">{brand()}<p>Sites personalizados. Sistemas financeiros.<br>Tecnologia para a rotina do seu negócio.</p></div><div class="footer-links"><p class="label">Explore</p><a href="index.html#solucoes">Soluções</a><a href="index.html#projetos">Projetos</a><a href="index.html#produtos">O que criamos</a><a href="repertoire.html">Portfólio completo</a><a href="prices.html">Serviços</a></div><div class="footer-links"><p class="label">Conecte-se</p><a href="contact.html">Contato</a>{external(GITHUB.rstrip('/'),'GitHub ↗')}{external(LINKEDIN,'LinkedIn ↗')}<a href="privacy.html">Privacidade</a><a href="security.html">Segurança</a></div></div><div class="footer-bottom"><span>© <span id="year" data-year>2026</span> MATRIZ. Tecnologia aplicada.</span><span>Projetos sob medida, do início à evolução.</span></div><div class="footer-wordmark" aria-hidden="true">MATRIZ</div></div></footer>'''
def write_page(path,title,description,body,*,noindex=False,contact=False):
    url=BASE+('' if path=='index.html' else path)
    csp="default-src 'self'; base-uri 'none'; object-src 'none'; frame-src 'none'; media-src 'none'; worker-src 'none'; font-src 'self'; img-src 'self'; style-src 'self'; script-src 'self'; connect-src "+("https://api.web3forms.com" if contact else "'none'")+"; form-action "+("https://api.web3forms.com" if contact else "'none'")+"; upgrade-insecure-requests"
    html=f'''<!doctype html>
<html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta http-equiv="Content-Security-Policy" content="{csp}"><meta name="referrer" content="strict-origin-when-cross-origin"><meta name="theme-color" content="#0A0B0D"><meta name="color-scheme" content="dark"><meta name="robots" content="{'noindex,follow' if noindex else 'index,follow'}"><title>{e(title)}</title><meta name="description" content="{e(description)}"><link rel="canonical" href="{url}">
<meta property="og:locale" content="pt_BR"><meta property="og:type" content="website"><meta property="og:site_name" content="MATRIZ"><meta property="og:title" content="{e(title)}"><meta property="og:description" content="{e(description)}"><meta property="og:url" content="{url}"><meta property="og:image" content="{BASE}assets/brand/logo-matriz.png"><meta property="og:image:width" content="1254"><meta property="og:image:height" content="1254"><meta property="og:image:alt" content="Símbolo oficial da MATRIZ: cubo branco e chama vermelha, laranja e amarela."><meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="{e(title)}"><meta name="twitter:description" content="{e(description)}"><meta name="twitter:image" content="{BASE}assets/brand/logo-matriz.png">
<link rel="icon" href="assets/brand/logo-matriz.png" type="image/png" sizes="1254x1254"><link rel="apple-touch-icon" href="assets/brand/logo-matriz.png"><link rel="manifest" href="site.webmanifest"><link rel="stylesheet" href="assets/css/matriz.css"><script src="assets/js/site.js" defer></script>{'<script src="assets/js/contact-bundle.js" defer></script>' if contact else ''}</head>
<body class="page-{'home' if path == 'index.html' else path.removesuffix('.html')}" itemscope itemtype="https://schema.org/Organization"><meta itemprop="url" content="{BASE}">{nav(path)}<main id="main-content">{body}</main>{footer()}</body></html>'''
    if path=='404.html':
        # A Pages 404 is also served for arbitrarily nested URLs.
        import re
        html=re.sub(r'((?:href|src)=")(?!(?:https?:|#))([^\"]+)',lambda m:m[1]+'/matriz/'+m[2],html)
    (ROOT/path).write_text(html+'\n')

def architecture(p):
    boxes='<span aria-hidden="true">→</span>'.join(f'<b>{e(x)}</b>' for x in p['diagram'])
    return f'<div class="architecture-art"><div class="label">{e(p["name"])} / fluxo da solução</div><div class="architecture-flow">{boxes}</div><p>{e(" · ".join(p["stack"][:3]))}</p><div class="architecture-note">Diagrama de funcionamento</div></div>'
def visual(p):
    image=p.get('image_webp',p.get('image'))
    if image:return f'<img src="{e(image)}" alt="{e(p["image_alt"])}" width="{p.get('image_width',1440)}" height="{p.get('image_height',900)}" loading="lazy" decoding="async">'
    return architecture(p)

def project_screenshots(p):
    if not p.get('image'): return ''
    images=[p]+p.get('gallery',[])
    return ''.join(f'''<figure class="case-screenshot"><a href="{e(item['image'])}" target="_blank" rel="noopener noreferrer" aria-label="Ampliar imagem de {e(p['name'])}"><img src="{e(item.get('image_webp',item['image']))}" alt="{e(item['image_alt'])}" width="{item.get('image_width',1440)}" height="{item.get('image_height',900)}" loading="lazy" decoding="async"></a><figcaption>{e(item.get('image_note','Captura real da interface do repositório.'))} <a class="expand-image" href="{e(item['image'])}" target="_blank" rel="noopener noreferrer">Ampliar imagem ↗</a></figcaption></figure>''' for item in images)
def case_tile(p,large=False):
    preview_note={'concept':'Referência visual','anonymized':'Imagem anonimizada'}.get(p.get('image_kind'))
    preview_badge=f'<span class="preview-note">{preview_note}</span>' if preview_note else ''
    image_class=(' has-image'+(' output-preview' if p.get('image_kind')=='output' else '')) if p.get('image') else ''
    image_caption='<p class="preview-description">Saída do projeto com dados de demonstração</p>' if p.get('image_kind')=='output' else ''
    zoom=external(p['image'],'Ampliar prévia <span aria-hidden="true">↗</span>','case-discover preview-zoom') if p.get('image') else ''
    if large:return f'''<article class="case large reveal"><a class="case-visual" href="{p['page']}" aria-label="Conhecer o projeto {e(p['name'])}">{visual(p)}</a><div class="case-copy"><p class="label">Projeto em foco / {e(p['category'])}</p><h3><a href="{p['page']}">{e(p['name'])}</a></h3><p>{e(p.get('client_summary',p['summary']))}</p><div class="case-meta"><span class="status-tag">{e(p.get('display_status',p['status']))}</span></div><a class="text-link" href="{p['page']}">Conhecer o projeto <span aria-hidden="true">↗</span></a></div></article>'''
    return f'''<article class="case reveal{image_class}" data-project-group="{e(p.get('group','gestao'))}"><a href="{p['page']}" aria-label="Conhecer o projeto {e(p['name'])}"><div class="case-visual">{visual(p)}{preview_badge}</div>{image_caption}<p class="project-use">{e(p.get('use',p['category']))}</p><div class="case-caption"><h3>{e(p['name'])}</h3><span aria-hidden="true">↗</span></div></a><p>{e(p.get('client_summary',p['summary']))}</p><div class="case-meta"><span class="status-tag">{e(p.get('display_status',p['status']))}</span><a class="case-discover" href="{p['page']}">Conhecer o projeto <span aria-hidden="true">↗</span></a>{zoom}</div></article>'''
def cta():return f'''<section class="contact-band"><div class="container"><div><p class="label">Vamos conversar</p><h2 id="cta-title">Seu negócio tem uma história.<br>Vamos construir o próximo capítulo.</h2><p>Conte sua ideia ou o que está dificultando a rotina. A gente ajuda a definir por onde começar.</p></div><div class="band-action">{action('contact.html','Conversar sobre meu negócio')}<p>Primeiro, entendemos. Depois, propomos.</p></div></div></section>'''

def product_options():
    products=[
        ('01','Catálogos, lojas e pedidos','Para o cliente encontrar seus produtos e comprar com mais facilidade.','Vitrine de produtos, cardápio digital, pedidos e integrações de pagamento conforme o projeto.','nossas-delicias.html','Ver um projeto de confeitaria','web','Catálogo e pedidos'),
        ('02','Agenda e relacionamento','Para organizar atendimentos e acompanhar seus clientes.','Agenda, cadastro de clientes, histórico de atendimento e lembretes definidos para a sua operação.','clientflow.html','Conhecer o protótipo ClientFlow','sistemas','Agenda e clientes'),
        ('03','Custos e precificação','Para entender quanto custa produzir e definir melhor seus preços.','Planilhas e sistemas que conectam insumos, receitas, custos, margem e vendas.','precificacao-vendas.html','Conhecer a planilha demonstrativa','automacao','Custos e precificação'),
        ('04','Painéis e relatórios','Para enxergar as informações que ajudam a tomar decisões.','Indicadores de vendas, filtros por período e relatórios a partir dos dados do seu negócio.','analise-vendas.html','Conhecer o projeto de análise de vendas','dados','Painéis e relatórios')]
    return ''.join(f'''<details class="product-option"><summary><span class="label product-number">{number}</span><span><strong>{title}</strong><span class="product-purpose">{purpose}</span></span><span class="product-toggle" aria-hidden="true"></span></summary><div class="product-content"><p>{description}</p><div class="product-actions"><a class="text-link" href="{page}">{label} <span aria-hidden="true">↗</span></a><a class="text-link" href="contact.html?service={service}&amp;project={quote(project)}">Quero para meu negócio <span aria-hidden="true">↗</span></a></div></div></details>''' for number,title,purpose,description,page,label,service,project in products)

def faq():
    items=[
        ('Preciso saber exatamente o que quero?','Pode chegar com uma ideia, uma referência ou um problema da rotina. Vamos entender como seu negócio funciona e ajudar a definir uma primeira entrega útil.'),
        ('Vocês fazem algo para uma loja pequena?','Sim. Um site, um catálogo ou um controle financeiro pode ser o primeiro passo. O tamanho do projeto acompanha a sua necessidade, e as próximas etapas podem ser planejadas depois.'),
        ('Quanto custa e quanto tempo leva?','Depende do que será construído. Antes de começar, a proposta apresenta funcionalidades, etapas, prazo e investimento. Hospedagem, licenças e serviços externos são informados quando necessários.'),
        ('Meu site vai funcionar no celular?','Os sites são desenvolvidos para se adaptar ao celular e ao computador. Nos sistemas, os recursos e as telas são planejados de acordo com quem vai usá-los.'),
        ('E se eu precisar de ajuda ou mudanças depois?','Na proposta, combinamos a entrega, a orientação de uso e as condições de suporte. Manutenção, novas funções e acompanhamento contínuo podem ser definidos conforme a necessidade.')]
    return '<div class="faq-list">'+''.join(f'<details class="faq-item"><summary>{question}<span aria-hidden="true"></span></summary><p>{answer}</p></details>' for question,answer in items)+'</div>'

def repertoire_rows():
    categories=['Todos']+[c for c in ['Sistemas','Automação','Dados','IA','Backend','Web'] if any(p['category']==c for p in PROJECTS)]
    filters=''.join(f'<button class="filter-button" type="button" data-filter="{e(cat)}" aria-pressed="{str(cat=="Todos").lower()}">{cat}</button>' for cat in categories)
    rows=''.join(f'<a class="repo-row" href="{repo_url(p)}" target="_blank" rel="noopener noreferrer" data-category="{e(p["category"])}" data-repo="{e(p["repo"])}"'+(' data-kind="fork"' if p.get('fork') else '')+f'><h3>{e(p["name"])}</h3><p>{e(p["summary"])}</p><span class="repo-kind">{e(p["status"])}</span><span aria-hidden="true">↗</span></a>' for p in PROJECTS)
    return f'<div class="filter-bar"><div class="filters" role="group" aria-label="Filtrar repertório por área">{filters}</div><p class="result-count" id="repo-count" aria-live="polite" role="status">{len(PROJECTS)} repositórios</p></div><div class="repertoire">{rows}</div>'

def portfolio_page():
    order=['finance-manager','coffee_five_site','nossas-delicias-site','projeto-petshop','bakery-manager','clientflow','projeto_academia','csv-sales-analyzer','decisionforge-ai','curtailment-intelligence']
    cases=[next(p for p in FEATURED if p['repo']==repo) for repo in order]
    groups=[('Todos','Todos os projetos'),('web','Sites e lojas'),('gestao','Sistemas e gestão'),('dados','Planilhas e dados')]
    filters=''.join(f'<button class="filter-button" type="button" data-project-filter="{key}" aria-controls="portfolio-projects" aria-pressed="{str(key=="Todos").lower()}">{label}</button>' for key,label in groups)
    body=f'''<div class="container"><section class="page-hero"><div class="breadcrumb"><a href="index.html">MATRIZ</a><span>/</span><span>Portfólio</span></div><p class="eyebrow label">Conheça o que construímos</p><h1>Uma necessidade real.<br><span class="accent">Uma solução com forma.</span></h1><p>De um site com a cara da sua marca a ferramentas para organizar o negócio. Explore os projetos pelo que você precisa.</p><div class="actions">{action('contact.html','Quero uma solução para meu negócio',True)}<a class="text-link" href="#projetos">Explorar os projetos <span aria-hidden="true">↓</span></a></div></section><section class="case-section" id="projetos"><div class="filter-bar"><div class="filters" role="group" aria-label="Filtrar projetos por necessidade">{filters}</div><p class="result-count" id="project-count" role="status" aria-live="polite">{len(cases)} projetos</p></div><div class="project-list portfolio-projects" id="portfolio-projects">{''.join(case_tile(p) for p in cases)}</div><p class="scope-note">Projetos, propostas e demonstrações têm estágios diferentes. Cada página explica o que foi construído, as referências visuais e as possibilidades de evolução.</p></section><section class="case-section upcoming-project"><div><p class="eyebrow label">Também estamos construindo</p><h2>SICMA</h2><p>Um novo projeto em Java e Spring Boot, ainda em desenvolvimento.</p></div>{action('sicma.html','Acompanhar o projeto')}</section><section class="case-section" id="repertorio"><details class="technical-details"><summary>Quer conhecer o código e a parte técnica?<span aria-hidden="true"></span></summary><div class="technical-content"><h2>Código dos projetos</h2><p>Acesse os repositórios que compõem esta seleção.</p>{repertoire_rows()}<p class="scope-note">A seleção prioriza projetos com interface, regras de negócio, integração ou análise documentada. Exercícios de cursos e forks ficam fora do portfólio comercial.</p></div></details></section></div>{cta()}'''
    write_page('repertoire.html','Portfólio — Sites e sistemas | MATRIZ','Conheça sites, sistemas financeiros, planilhas e soluções de dados desenvolvidos pela MATRIZ. Filtre os projetos pela necessidade do seu negócio.',body)

