def project_pages():
    for i,p in enumerate(CASES):
        if p['repo']=='Sicma-JAVA':
            sicma_page(p)
            continue
        features=''.join(f'<li>{e(x)}</li>' for x in p['features'])
        flow=''.join(f'<li><h3>{e(a)}</h3><p>{e(b)}</p></li>' for a,b in p['flow'])
        stack=''.join(f'<span>{e(x)}</span>' for x in p['stack'])
        sources=' · '.join(external(GITHUB+p['repo']+'/blob/'+p.get('branch','main')+'/'+quote(path),e(path)) for path in p['evidence'])
        visible_index=next((i for i,item in enumerate(VISIBLE_CASES) if item['repo']==p['repo']),-1)
        nxt=VISIBLE_CASES[(visible_index+1)%len(VISIBLE_CASES)]
        screenshot=project_screenshots(p)
        body=f'''<div class="container"><section class="page-hero"><div class="breadcrumb"><a href="index.html">MATRIZ</a><span>/</span><a href="index.html#projetos">Projetos</a><span>/</span><span>{e(p['name'])}</span></div><p class="eyebrow label">{e(p.get('use',p['category']))}</p><h1>{e(p['headline'])}</h1><p>{e(p.get('client_summary',p['summary']))}</p><div class="case-meta"><span class="status-tag">{e(p.get('display_status',p['status']))}</span></div><div class="actions">{action('contact.html?service='+p['service']+'&project='+quote(p['name']),'Quero uma solução assim',True)}{external(p['demo'],'Abrir demonstração <span aria-hidden="true">↗</span>','button secondary') if p.get('demo') else ''}</div></section>
<div class="case-layout"><aside class="case-index" aria-label="Nesta página"><p class="label">Dentro do projeto</p><a href="#visao">Visão geral</a><a href="#fluxo">Como funciona</a><a href="#recursos">O que foi desenvolvido</a><a href="#arquitetura">Detalhes técnicos</a><a href="#status">Status e evolução</a></aside><div class="case-content"><section class="case-section" id="visao">{screenshot}<div class="two-cols"><div><p class="eyebrow label">O problema</p><h2>O que precisa mudar?</h2><p>{e(p['problem'])}</p></div><div><p class="eyebrow label">A solução</p><h2>O que foi construído.</h2><p>{e(p['solution'])}</p></div></div></section><section class="case-section" id="fluxo"><h2>Como funciona.</h2><ol class="case-flow">{flow}</ol></section><section class="case-section" id="recursos"><h2>O que foi desenvolvido.</h2><ul class="feature-list">{features}</ul></section><section class="case-section" id="arquitetura"><details class="technical-details"><summary>Conheça a tecnologia do projeto<span aria-hidden="true"></span></summary><div class="technical-content"><h2>A engenharia por trás.</h2><p>{e(p['architecture'])}</p><div class="tech-list">{stack}</div>{architecture(p)}<div class="actions">{external(repo_url(p),'Ver código no GitHub <span aria-hidden="true">↗</span>','button secondary')}</div></div></details></section><section class="case-section" id="status"><h2>O estágio atual. O próximo passo.</h2><p class="source-note">{e(p['limits'])}</p><h3>Possibilidades de evolução</h3><p>{e(p['evolution'])}</p><p class="research-note">Fontes consultadas: {sources}.</p></section><a class="case-next" href="{nxt['page']}"><div><p class="label">Próximo projeto</p><strong>{e(nxt['name'])}</strong></div><span aria-hidden="true">↗</span></a></div></div></div>{cta()}'''
        write_page(p['page'],p['name']+' — Projetos MATRIZ',p['summary'],body,noindex=not p.get('listed',True))

def sicma_page(p):
    body=f'''<div class="container"><section class="page-hero"><div class="breadcrumb"><a href="index.html">MATRIZ</a><span>/</span><a href="repertoire.html">Portfólio</a><span>/</span><span>SICMA</span></div><p class="eyebrow label">Java / Spring Boot</p><h1>SICMA</h1><p>Um projeto em desenvolvimento.<br>A próxima versão está em preparação.</p><div class="case-meta"><span class="status-tag">Em desenvolvimento</span></div><div class="actions">{external(repo_url(p),'Acompanhar no GitHub <span aria-hidden="true">↗</span>','button primary')}<a class="text-link" href="repertoire.html">Voltar ao portfólio <span aria-hidden="true">↗</span></a></div></section><section class="case-section sicma-status"><h2>Acompanhe a construção.</h2><p>O repositório público já contém a estrutura inicial em Java 17, Spring Boot e Gradle. A implementação do sistema será adicionada em uma próxima atualização.</p><p>Quando a nova versão estiver disponível, esta página poderá apresentar suas funcionalidades e demonstração.</p><div class="tech-list"><span>Java 17</span><span>Spring Boot</span><span>Gradle</span></div></section></div>{cta()}'''
    write_page('sicma.html','SICMA — Projeto Java | MATRIZ',p['summary'],body)

